<?php $activeAdminCount = count(array_filter($users, static fn (array $user): bool => $user['role'] === 'admin' && (int) $user['is_active'] === 1)); ?>
<section class="page-heading"><p class="eyebrow">Pengaturan akses</p><h1>Pengguna</h1><p>Tambahkan, ubah, nonaktifkan, atau hapus akun. Minimal satu akun administrator aktif harus selalu tersedia.</p></section>
