<details class="form-section settings-form" open><summary>Tambah pengguna</summary><form method="post" action="/settings/users" class="data-form"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><div class="field-grid"><label>Nama lengkap *<input name="full_name" required maxlength="150"></label><label>Username *<input name="username" required maxlength="64"></label><label>Password *<input name="password" type="password" required minlength="8"></label><label>Peran *<select name="role"><option value="perawat">Perawat</option><option value="admin">Admin</option></select></label></div><div class="form-actions"><button type="submit">Tambah pengguna</button></div></form></details>
<section class="form-section"><h2>Daftar pengguna</h2><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Username</th><th>Peran</th><th>Status</th><th>Password baru</th><th>Aksi</th></tr></thead><tbody><?php foreach ($users as $user): ?><?php $isCurrentUser = (int) $user['id'] === $currentUserId; $isLastActiveAdmin = $user['role'] === 'admin' && (int) $user['is_active'] === 1 && $activeAdminCount <= 1; $cannotDelete = $isCurrentUser || $isLastActiveAdmin; $deleteReason = $isCurrentUser ? 'Akun yang sedang digunakan tidak dapat dihapus.' : ($isLastActiveAdmin ? 'Minimal satu administrator aktif harus tersedia.' : ''); ?><tr><td><form id="user-<?= (int)$user['id'] ?>" method="post" action="/settings/users/<?= (int)$user['id'] ?>"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><input name="full_name" value="<?= View::e($user['full_name']) ?>" required maxlength="150"></form></td><td><input form="user-<?= (int)$user['id'] ?>" name="username" value="<?= View::e($user['username']) ?>" required maxlength="64"></td><td><select form="user-<?= (int)$user['id'] ?>" name="role"><option value="perawat" <?= $user['role']==='perawat'?'selected':'' ?>>Perawat</option><option value="admin" <?= $user['role']==='admin'?'selected':'' ?>>Admin</option></select></td><td><label><input form="user-<?= (int)$user['id'] ?>" type="checkbox" name="is_active" value="1" <?= (int)$user['is_active']===1?'checked':'' ?>> Aktif</label></td><td><input form="user-<?= (int)$user['id'] ?>" name="password" type="password" minlength="8" placeholder="Kosongkan bila tetap"></td><td><div class="user-actions"><button form="user-<?= (int)$user['id'] ?>" type="submit">Simpan</button><form method="post" action="/settings/users/<?= (int)$user['id'] ?>/delete" onsubmit="return confirm('Hapus akun <?= View::e(addslashes($user['username'])) ?>? Tindakan ini tidak dapat dibatalkan.');"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><button type="submit" class="button-danger" <?= $cannotDelete ? 'disabled title="' . View::e($deleteReason) . '"' : '' ?>>Hapus akun</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section>
